  if(o.kind==='welder')return `<rect width="58" height="48" rx="2" fill="#ffc928" stroke="#513d00" stroke-width="2"/><path d="M5 5h48v11H5z" fill="#fff2aa" stroke="#725700"/><rect x="7" y="21" width="19" height="19" fill="#263d46"/><circle cx="38" cy="28" r="5" fill="#eb4f3d" stroke="#6e160e"/><path d="M32 39h19M36 35h11" stroke="#6f5400" stroke-width="2"/><text x="29" y="13" text-anchor="middle" font-size="8" font-weight="900">LASER</text><text x="29" y="57" text-anchor="middle" font-size="9" font-weight="bold">MÁY HÀN</text>`;
