function objectDisplayName(o){if(!o)return'Chọn người, bàn, máy hoặc băng tải';const kind={belt:'Băng tải 27 m',person:'Người ngồi',table:'Bàn',machine:'Máy',welder:'Máy hàn Laser',press:'Jig Press V3',attach:'Jig Attach',tool:'Tool'}[o.kind]||o.kind;return o.station?`${kind} · ${o.index+1}. ${o.station.name}`:o.isExtra?`${kind} · bản sao`:kind}
function updateLayoutToolbar(){if(!$('layoutEditorToolbar'))return;const o=selectedLayoutObject(),editable=canEdit()&&layoutEditMode;$('layoutEditorToolbar').hidden=!canEdit();$('selectedObjectName').textContent=objectDisplayName(o);$('layoutLockBtn').textContent=layoutEditMode?'Đang chỉnh sửa':'Đã khóa bố cục';$('layoutLockBtn').classList.toggle('active',layoutEditMode);$('rotateObjectBtn').disabled=!editable||!o;$('copyObjectBtn').disabled=!editable||!o||o.kind==='belt';$('duplicateObjectBtn').disabled=!editable||!o||o.kind==='belt';$('pasteObjectBtn').disabled=!editable||!layoutClipboard;$('snapObjectBtn').disabled=!editable||!o;$('deleteObjectBtn').disabled=!editable||!o?.isExtra}
function rotateSelectedObject(){const o=selectedLayoutObject();if(!o||!canEdit()||!layoutEditMode)return;snapshot();saveObjectPosition(o,o.x,o.y,((o.rotation||0)+90)%360);renderEquipmentDiagram();scheduleSave();toast('Đã xoay 90°')}
