function pasteLayoutObject(){if(!layoutClipboard||!canEdit()||!layoutEditMode)return;const base=selectedLayoutObject(),id='obj-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),extra={...structuredClone(layoutClipboard),id,x:Math.min(1960,(base?.x||80)+34),y:Math.min(620,(base?.y||80)+34)};snapshot();model().layoutExtras=model().layoutExtras||[];model().layoutExtras.push(extra);selectedObjectUid='extra:'+id;renderAll();scheduleSave();toast('Đã dán bản sao; kéo đến vị trí cần đặt')}
